class Solution {
public:
    int distanceSum(int m, int n, int k) {
        const long long MOD = 1000000007LL;
        int N = m * n;
        vector<long long> fact(N + 1, 1), inv_fact(N + 1, 1);
        for (int i = 1; i <= N; i++) fact[i] = fact[i-1] * i % MOD;
        auto pw = [&](long long b, long long e) { long long r = 1; b %= MOD; while (e) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; } return r; };
        inv_fact[N] = pw(fact[N], MOD - 2);
        for (int i = N; i >= 1; i--) inv_fact[i-1] = inv_fact[i] * i % MOD;
        auto C = [&](int a, int b) { return fact[a] * inv_fact[b] % MOD * inv_fact[a-b] % MOD; };
        long long Sx = (long long)m * (m * (long long)m - 1) / 6;
        long long Sy = (long long)n * (n * (long long)n - 1) / 6;
        long long total = ((long long)n * Sx + (long long)m * Sy) % MOD;
        return C(N - 2, k - 2) * total % MOD;
    }
};

