class Solution {
    public int distanceSum(int m, int n, int k) {
        final long MOD = 1000000007L;
        int N = m * n;
        long[] fact = new long[N + 1], invFact = new long[N + 1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) fact[i] = fact[i-1] * i % MOD;
        invFact[N] = pow(fact[N], MOD - 2, MOD);
        for (int i = N; i >= 1; i--) invFact[i-1] = invFact[i] * i % MOD;
        long comb = fact[N-2] * invFact[k-2] % MOD * invFact[N-k] % MOD;
        long sx = (long) m * ((long) m * m - 1) / 6;
        long sy = (long) n * ((long) n * n - 1) / 6;
        long total = ((long) n * sx + (long) m * sy) % MOD;
        return (int) (comb * total % MOD);
    }
    private long pow(long b, long e, long mod) { long r = 1; b %= mod; while (e > 0) { if ((e & 1) == 1) r = r * b % mod; b = b * b % mod; e >>= 1; } return r; }
}

