var distanceSum = function(m, n, k) {
    const MOD = 1000000007n, B = BigInt;
    const N = B(m * n);
    const fact = [1n];
    for (let i = 1n; i <= N; i++) fact.push(fact[i - 1n] * i % MOD);
    const pw = (b, e) => { let r = 1n; b %= MOD; while (e > 0n) { if (e & 1n) r = r * b % MOD; b = b * b % MOD; e >>= 1n; } return r; };
    const invF = pw(fact[Number(N)], MOD - 2n);
    const comb = fact[Number(N) - 2] * invF % MOD * pw(fact[k - 2] * fact[Number(N) - k] % MOD, MOD - 2n) % MOD;
    const sx = B(m) * (B(m) * B(m) - 1n) / 6n, sy = B(n) * (B(n) * B(n) - 1n) / 6n;
    const total = (B(n) * sx + B(m) * sy) % MOD;
    return Number(comb * total % MOD);
};
